import{z as A,x as n,o as i,c as s,q as e,j as r,D as a,d as t,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"泰勒原理","description":"","frontmatter":{"title":"泰勒原理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/taylor-principle.md","filePath":"econ/taylor-principle.md","lastUpdated":1791063341000}'),B={name:"econ/taylor-principle.md"};function d(_,E,h,C,c,m){const p=n("Mermaid");return i(),s("div",null,[E[2]||(E[2]=e('<h1 id="泰勒原理" tabindex="-1">泰勒原理 <a class="header-anchor" href="#泰勒原理" aria-label="Permalink to &quot;泰勒原理&quot;">​</a></h1><div class="epigraph"><p>名义利率对通胀的长期反应必须大于一对一，实际利率才能在通胀上升时上升；这是确定性条件，不是某十年的拟合优度。</p><footer>—— Woodford 对利率规则确定性的讨论；Clarida, Galí and Gertler 对反应系数的估计对照</footer></div><p><a href="/econ/taylor-rule">上一课</a>已经写出 \\(i_t=r^*+\\pi^*+\\phi_\\pi(\\pi_t-\\pi^*)+\\phi_y\\tilde{y}_t\\)，并把 \\(\\phi_\\pi\\gt 1\\) 叫做泰勒原则。本课的缺口不是再抄一遍规则，而是：为什么小于一对一的反应会让通胀自我实现，以及 Clarida–Galí–Gertler 如何把这条不等式读成制度分界。时间不一致是下一课：即使系数写对了，将来的自己是否还肯遵守。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新凯恩斯系统是前瞻 IS + NKPC + 利率规则。若 \\(\\phi_\\pi\\le 1\\)，通胀预期上升时实际利率不升甚至下降，欧拉要求当前需求更旺，NKPC 上 \\(\\pi\\) 进一步升——存在许多条都自洽的通胀路径，价格水平不确定。Woodford 的缺口是局部确定性：规则必须对名义变量有足够反应，理性预期均衡才唯一（在稳态附近）。Taylor 原文的 1.5 是经验描述；原理是不等式，不是那个点估计。</p><p>上一课已经写出规则并点过 \\(\\phi_\\pi\\gt 1\\)。本课只证明为什么小于一对一会让通胀自我实现，并把 Clarida–Galí–Gertler 的分样本当作制度对照，而不是再拟合一条泰勒规则。时间不一致下一课才问：写对的系数将来还肯不肯遵守。</p><p><span class="marginnote">数字实例看「一对一」卡在哪：通胀高出目标 2 个百分点时——若 \\(\\phi_\\pi=1\\)，名义利率只多加 2 个点，实际利率 \\(i-\\pi\\) 一动不动，等于没反应；\\(\\phi_\\pi=1.5\\) 才多加 3 个点，实际利率真正上升 1 个点。「大于一」要求的就是这多出来的那截。</span></p><p><span class="marginnote">\\(\\phi_\\pi\\gt 1\\) 是对<strong>通胀</strong>的反应。对产出缺口的 \\(\\phi_y\\) 帮助区分需求与成本冲击，但单独把 \\(\\phi_y\\) 加大并不能替代对 \\(\\pi\\) 的激进反应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把三方程对数线性系统写成对 \\(\\mathbb{E}\\pi\\)、\\(\\tilde{y}\\) 的差分方程，检查特征根是否落在确定性区域。简单情形下，长期反应系数 \\(\\phi_\\pi\\gt 1\\) 即泰勒原理；有惯性、有前瞻、有 \\(\\phi_y\\) 时，边界会平移，但精神不变：通胀升，实际利率必须升。Clarida、Galí 与 Gertler（QJE 2000）用前瞻规则估美国：Volcker 之前 \\(\\phi_\\pi\\) 往往小于一，之后大于一——把「大稳健」读成确定性区域的切换，而不是偏好突然变好。</p>',10)),(i(),r(o,null,{default:a(()=>[l(p,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20PHI%7B%22%CF%86%CF%80%20%EF%BC%9E%201%20%3F%22%7D%0A%20%20PHI%20--%3E%7C%E6%98%AF%7C%20UP%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20UP%20--%3E%20DOWN%5B%22%E9%9C%80%E6%B1%82%E4%B8%8E%20%CF%80%20%E8%A2%AB%E5%8E%8B%E5%9B%9E%22%5D%0A%20%20PHI%20--%3E%7C%E5%90%A6%7C%20SELF%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E4%B8%8D%E5%8D%87%22%5D%0A%20%20SELF%20--%3E%20MULT%5B%22%E5%A4%9A%E6%9D%A1%E9%80%9A%E8%83%80%E8%B7%AF%E5%BE%84%E8%87%AA%E6%B4%BD%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>操作上，走廊或地板系统让 \\(M\\) 内生，数量方程不再是工具。原理约束的是 \\(i\\) 对 \\(\\pi\\) 的映射，不是准备金数量。</p><h3 id="惯性不是放弃原理" tabindex="-1">惯性不是放弃原理 <a class="header-anchor" href="#惯性不是放弃原理" aria-label="Permalink to &quot;惯性不是放弃原理&quot;">​</a></h3><p>规则含 \\(i_{t-1}\\) 时，短期可以「少动」，但长期乘数仍须 \\(\\phi_\\pi\\gt 1\\)。惯性来自承诺下的历史依赖，不是把反应改成适应性微调。卢卡斯批判：用 Volcker 之前的简化式去模拟「若当时就激进加息」，系数本身不可搬运。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公众若相信 \\(\\phi_\\pi\\gt 1\\)，则不敢把 \\(\\mathbb{E}\\pi\\) 任意抬高：那样会换来更高的实际利率与更低的缺口。锚住的是预期，不只是当期 \\(i\\)。\\(\\phi_\\pi\\le 1\\) 时，预言高通胀可以自实现，铸币税与价格水平一起漂。这与长期中性兼容：原理选的是哪一条中性路径（哪一个 \\(\\pi^*\\)），不是否认 \\(y\\) 回自然率。</p><p>成本推动下，激进加息压 \\(\\pi\\) 会暂时加大缺口——那是权衡，不是对原理的否证。原理管确定性；最优系数还要看损失函数，下一课的承诺问题在此接头。\\(r^*\\) 作为截距：原理约束的是对 \\(\\pi\\) 的斜率，截距跟错自然利率会带来平均缺口，那是测量问题，不取消 \\(\\phi_\\pi\\gt 1\\)。</p><p>财政若主动（FTPL 课），货币再怎么满足泰勒原理也可能与盈余规则冲突。本课先在被动财政、正利率区把不等式钉死。开放经济的 UIP 会把外国 \\(i^*\\) 与 \\(\\mathbb{E}\\Delta e\\) 写进确定性边界，蒙代尔再碰，这里封闭。</p><p><span class="marginnote">有效下限上 \\(\\phi_\\pi\\gt 1\\) 无法执行，确定性要靠对未来路径的承诺。那是零下限课，本课先在正利率区把不等式钉死。</span></p><p><span class="marginnote">常见误区：初学者容易把泰勒原理读成「通胀来了就加息」这句口号。真正的分界不在加不加，而在加得<strong>够不够多</strong>：名义利率的加幅必须盖过通胀本身的涨幅，实际利率才会上升、需求才会收缩。加是加了但没加够，恰恰是最危险的区间——市场看到央行出手了，通胀预期反而更有胆量往上走。</span></p>',9)),(i(),r(o,null,{default:a(()=>[l(p,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%85%AC%E4%BC%97%E8%AF%95%E7%9D%80%E6%8A%AC%E9%AB%98%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20FB%7B%22%E8%A7%84%E5%88%99%E5%8F%AF%E4%BF%A1%E4%B8%94%20%CF%86%CF%80%20%EF%BC%9E%201%EF%BC%9F%22%7D%0A%20%20FB%20--%3E%7C%22%E6%98%AF%22%7C%20HI%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E7%AB%8B%E5%88%BB%E4%B8%8A%E5%8D%87%EF%BC%8C%E9%9C%80%E6%B1%82%E6%94%B6%E7%BC%A9%22%5D%0A%20%20HI%20--%3E%20BACK%5B%22%E6%8A%A2%E5%85%88%E6%B6%A8%E4%BB%B7%E4%B8%8D%E5%88%92%E7%AE%97%EF%BC%8C%E9%A2%84%E6%9C%9F%E8%A2%AB%E5%8E%8B%E5%9B%9E%22%5D%0A%20%20BACK%20--%3E%20ANCHOR%5B%22%E9%A2%84%E6%9C%9F%E9%94%9A%E5%AE%9A%EF%BC%9A%E5%BE%88%E5%B0%91%E9%9C%80%E8%A6%81%E7%9C%9F%E7%9A%84%E5%A4%A7%E5%8A%9B%E5%8A%A0%E6%81%AF%22%5D%0A%20%20FB%20--%3E%7C%22%E5%90%A6%22%7C%20WEAK%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E4%B8%8D%E5%8D%87%E7%94%9A%E8%87%B3%E4%B8%8B%E9%99%8D%22%5D%0A%20%20WEAK%20--%3E%20MORE%5B%22%E9%9C%80%E6%B1%82%E6%9B%B4%E6%97%BA%EF%BC%8C%E9%AB%98%E9%80%9A%E8%83%80%E8%87%AA%E6%88%91%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20MORE%20--%3E%20E%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重估 CGG 的样本，不把原理写成每个国家的法定公式。汇率与 UIP 会改变开放经济的确定性边界，蒙代尔再碰。量化栏的微观报价不是 \\(\\phi_\\pi\\)。也不要把「规则含资产价格」偷运进来：那是另一条反应函数。</p><p>Woodford 的确定性是局部的、线性化的。全局上还可能有流动性陷阱式的第二稳态，那是下限课的对象，不在本课把 \\(\\phi_\\pi\\gt 1\\) 说成全球唯一。简单规则的惯性、前瞻、对缺口的反应都会平移边界，精神仍是：通胀升，实际利率必须升。财政主动时原理可能与盈余规则冲突，FTPL 课再写，这里假定财政被动。</p><p>后课默认：利率规则先满足 \\(\\phi_\\pi\\gt 1\\)，均衡才按局部唯一来读。下一课问：宣布这条规则的央行，将来有没有再偷一次意外通胀的激励。</p><p><span class="marginnote">CGG 分样本的直觉：Volcker 之前估出 \\(\\phi_\\pi\\lt 1\\)，不是说他之前的央行「毫不作为」，而是反应幅度不够一对一，通胀预期处在自我实现的危险区；Volcker 之后系数翻过一，同样的经济换了一组预期均衡。这把「大稳健」读成制度切换，而不是运气或偏好突变。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>泰勒原理：\\(\\phi_\\pi\\gt 1\\)，通胀升则实际利率升。</li><li>它是 NK 系统的确定性条件，不是 Taylor 1993 的点估计。</li><li>CGG：反应系数跨 Volcker 的切换，是制度对照。</li><li>惯性改变短期动态，不取消长期大于一对一。</li><li>下限上原理无法执行，确定性改靠路径承诺。</li><li>出处：Woodford, <em>Interest and Prices</em>；Clarida, Galí and Gertler, <em>QJE</em> 2000。</li></ul>',7))])}const P=A(B,[["render",d]]);export{F as __pageData,P as default};
